INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15501, 'Proverbs 3:34', 'Proverbs', 3, 34, '&nbsp;هغه د مغروره مسخره کوونکو پورې مسخرې کوى، خو په عاجز خويه باندې خپل فضل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15502, 'Proverbs 3:35', 'Proverbs', 3, 35, '&nbsp;هوښيار عزت په ميراث کښې ګټى، خو کم عقل خپل شرم زياتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15503, 'Proverbs 4:1', 'Proverbs', 4, 1, '&nbsp;زما زامنو د خپل پلار هدايت ته غوږ ونيسئ. او هغې ته توجو ورکړئ او پوهه حاصله کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15504, 'Proverbs 4:2', 'Proverbs', 4, 2, '&nbsp;ځکه چې زۀ تاسو ته ښۀ تعليم درښايم، نو زما تعليمات مۀ هېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15505, 'Proverbs 4:3', 'Proverbs', 4, 3, '&nbsp;هر کله چې زۀ د خپل پلار په کور کښې هلک وم، او د خپلې مور اېک يو نيازبين زوئ وم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15506, 'Proverbs 4:4', 'Proverbs', 4, 4, '&nbsp;هغۀ ما ته تعليم راکړو او وې وئيل، ”په خپل ټول زړۀ سره زما نصيحت راټينګ کړه، زما په حُکمونو عمل کوه نو ستا ژوند به په خير تير شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15507, 'Proverbs 4:5', 'Proverbs', 4, 5, '&nbsp;حِکمت حاصل کړه، او پوهه حاصله کړه، زما خبرې مۀ هېروه او مۀ د هغې نه مخ اړوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15508, 'Proverbs 4:6', 'Proverbs', 4, 6, '&nbsp;عقل ته مۀ شاه کوه، ځکه چې هغه به ستا حفاظت وکړى، د هغۀ سره مينه کوه نو هغه به په تا باندې نظر ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15509, 'Proverbs 4:7', 'Proverbs', 4, 7, '&nbsp;حِکمت حاصلول د ټولو نه اهم کار دے، د نورو څيزونو د حاصلولو سره سره پوهه هم حاصله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15510, 'Proverbs 4:8', 'Proverbs', 4, 8, '&nbsp;د حِکمت عزت کوه او دا به تا لوئ کړى. دې ته غاړه ورکړه نو دا به تا عزتمند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15511, 'Proverbs 4:9', 'Proverbs', 4, 9, '&nbsp;دا به ستا سر د فضل سهرې سره ښائسته کړى او د شان او شوکت تاج به در په سر کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15512, 'Proverbs 4:10', 'Proverbs', 4, 10, '&nbsp;زما زويه، ما ته غوږ شه. زۀ چې درته څۀ وايم هغه کوه، نو په دې کولو سره به ستا عمر اوږد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15513, 'Proverbs 4:11', 'Proverbs', 4, 11, '&nbsp;ما درته د عقل او حِکمت لارښودنه وکړه او په نېغه لار مې روان کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15514, 'Proverbs 4:12', 'Proverbs', 4, 12, '&nbsp;کله چې تۀ ګرځې نو ستا پښې به هيڅ څيز نۀ منع کوى، او کله چې تۀ منډه وهې نو تيندک به نۀ خورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15515, 'Proverbs 4:13', 'Proverbs', 4, 13, '&nbsp;زما نصيحتونه راټينګ کړه او دا مۀ پرېږده چې ستا نه لاړ شى. د هغوئ ښۀ حفاظت وکړه ځکه چې دا ستا ژوندون دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15516, 'Proverbs 4:14', 'Proverbs', 4, 14, '&nbsp;د شريرانو په لار کښې خپل قدم مۀ ږده او مۀ د بدکارانو په لار تلل کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15517, 'Proverbs 4:15', 'Proverbs', 4, 15, '&nbsp;د هغوئ د لارو نه ځان وساته، د هغوئ په لار مۀ ځه، د هغوئ د لارو نه راوګرځه او په خپله لار روان اوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15518, 'Proverbs 4:16', 'Proverbs', 4, 16, '&nbsp;ترڅو پورې چې دوئ غلط کار نۀ وى کړے تر هغې خوب نۀ ورځى، ترڅو پورې چې دوئ چا ته تيندک نۀ وى ورکړے نو دوئ تر هغې پورې آرام نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15519, 'Proverbs 4:17', 'Proverbs', 4, 17, '&nbsp;هغوئ د شرارت روټۍ خورى او د فساد نه ډک مے څښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15520, 'Proverbs 4:18', 'Proverbs', 4, 18, '&nbsp;د صادقانو لار د سحر د رڼا په شان ده، تر هغې ځليږى او لا نوره هم زياتيږى ترڅو چې د ورځې رڼا نۀ وى راښکاره شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15521, 'Proverbs 4:19', 'Proverbs', 4, 19, '&nbsp;خو د بدکارانو لار لکه د تورې تيارې په شان ده، دوئ په دې نۀ پوهيږى چې په څۀ باندې يې تيندک وخوړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15522, 'Proverbs 4:20', 'Proverbs', 4, 20, '&nbsp;زما زويه، زۀ چې درته څۀ وايم هغې ته توجو ورکړه، او په غور سره زما خبرې واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15523, 'Proverbs 4:21', 'Proverbs', 4, 21, '&nbsp;دا د خپل نظر نه مۀ وباسه او په خپل زړۀ کښې يې دننه وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15524, 'Proverbs 4:22', 'Proverbs', 4, 22, '&nbsp;نو دا به هغوئ له ژوند ورکړى چې څوک يې پېدا کوى، او د هغوئ ټول وجود له به صحت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15525, 'Proverbs 4:23', 'Proverbs', 4, 23, '&nbsp;د هر څۀ نه اول د خپل زړۀ خيال ساته، ځکه چې دا د ژوند د هدايت سرچينه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15526, 'Proverbs 4:24', 'Proverbs', 4, 24, '&nbsp;د خپلې ‎‎‎‎‎‎‎‎خولې نه ټګى لرې کړه، او دوکه مارې خبرې د خپلو شونډو نه لرې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15527, 'Proverbs 4:25', 'Proverbs', 4, 25, '&nbsp;په غور سره مخامخ نېغ ګوره، او خپل نظر نېغ وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15528, 'Proverbs 4:26', 'Proverbs', 4, 26, '&nbsp;او د خپلو قدمونو دپاره لاره هواره کړه، نو بيا به ستا ټوله لار مضبوطه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15529, 'Proverbs 4:27', 'Proverbs', 4, 27, '&nbsp;ښې او ګس طرف ته مۀ تاوېږه، او خپلې پښې د شرارت نه وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15530, 'Proverbs 5:1', 'Proverbs', 5, 1, '&nbsp;زما زويه، زما پوهې ته توجو ورکړه، او زما د حِکمت خبرو ته ښۀ غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15531, 'Proverbs 5:2', 'Proverbs', 5, 2, '&nbsp;نو بيا به تۀ تميز حاصل کړې، او ستا شونډې به عِلم او حِکمت محفوظوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15532, 'Proverbs 5:3', 'Proverbs', 5, 3, '&nbsp;ځکه چې د زناکارې ښځې د شونډو نه شات راڅاڅى. او د هغې خبرې د تېلو نه زياتې نرمې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15533, 'Proverbs 5:4', 'Proverbs', 5, 4, '&nbsp;خو په آخر کښې هغه د ګنډير په شان ترخه، او د دوه مخيزې تُورې په شان تيره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15534, 'Proverbs 5:5', 'Proverbs', 5, 5, '&nbsp;د هغې پښې د مرګ په طرف روانې دى، او د هغې قدمونه سيدها د قبر طرف ته لارښودنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15535, 'Proverbs 5:6', 'Proverbs', 5, 6, '&nbsp;هغه د ژوند د لارې په حقله سوچ نۀ کوى، د هغې لارې کږې وږې دى، خو هغه پرې نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15536, 'Proverbs 5:7', 'Proverbs', 5, 7, '&nbsp;نو بيا اوس زما زويه، ما ته غوږ ونيسه. او زۀ چې درته څۀ وايم نو د هغې نه مۀ اوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15537, 'Proverbs 5:8', 'Proverbs', 5, 8, '&nbsp;د داسې ښځې نه ځان لرې ساته. او چې د هغې د کور دروازې ته هم ورنزدې نۀ شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15538, 'Proverbs 5:9', 'Proverbs', 5, 9, '&nbsp;هسې نه چې خپل عزت نورو ته ورکړې او بې‌عزته شې. او د خپل ژوند واګې د ظالمانو رحم و کرم ته وسپارې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15539, 'Proverbs 5:10', 'Proverbs', 5, 10, '&nbsp;هسې نه چې پردى ستا په مال مزې وکړى، او ستا د ژوند محنت د بل چا کور مالا مال کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15540, 'Proverbs 5:11', 'Proverbs', 5, 11, '&nbsp;او د خپل عمر په آخر کښې به تۀ زبيرګى او فريادونه کوې، هرکله چې ستا غوښې او بدن خوړين شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15541, 'Proverbs 5:12', 'Proverbs', 5, 12, '&nbsp;نو تۀ به ووائې، ”ما د اصلاح نه څومره نفرت کولو. او څومره به زما زړۀ اصلاح کول رټل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15542, 'Proverbs 5:13', 'Proverbs', 5, 13, '&nbsp;ما به د خپلو اُستاذانو تابعدارى نۀ کوله، او نۀ به مې خپلو لارښودونکو ته غوږ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15543, 'Proverbs 5:14', 'Proverbs', 5, 14, '&nbsp;نو زۀ د تباهۍ په غاړه ولاړ يم، او په ډېرو خلقو کښې وشرمېدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15544, 'Proverbs 5:15', 'Proverbs', 5, 15, '&nbsp;د خپلې ذخيرې اوبۀ څښه، او صرف د خپلې ښځې سره کوروالے کوه لکه څنګه چې د خپل کوهى نه روانې اوبۀ څښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15545, 'Proverbs 5:16', 'Proverbs', 5, 16, '&nbsp;دا مناسب ده چې ستا چينې په کوڅو کښې، او ستا د اوبو لختى په چوکونو کښې وبهيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15546, 'Proverbs 5:17', 'Proverbs', 5, 17, '&nbsp;نو دا دې يواځې ستا وى، کله دې هم د پردو سره شريک نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15547, 'Proverbs 5:18', 'Proverbs', 5, 18, '&nbsp;ستا چينې دې برکتى شى، د خپلې ښځې سره خوشحاله اوسه چې ستا په ځوانۍ کښې ورسره وادۀ شوے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15548, 'Proverbs 5:19', 'Proverbs', 5, 19, '&nbsp;چې هغه د يوې ښُکلې مينه ناکې او مهربانه هوسۍ په شان ده نو د هغې د بدن ښُکلا دې تا معمور کړى، او تۀ دې هر وخت د هغې د مينې غلام يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15549, 'Proverbs 5:20', 'Proverbs', 5, 20, '&nbsp;زما زويه نو تۀ دې ولې د يوې زناکارې ښځې په مينه کښې راګېر يې؟ او تۀ ولې د بل سړى د ښځې سره يو ځائ کېږې او غاړه غټۍ کېږې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15550, 'Proverbs 5:21', 'Proverbs', 5, 21, '&nbsp;نو د انسان په ټولو لارو د مالِک خُدائ نظر دے، او هغه په خپله د هغۀ د ټولو لارو څارنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15551, 'Proverbs 5:22', 'Proverbs', 5, 22, '&nbsp;د شرير شرارت هم د هغۀ دپاره دام دے. او د هغۀ د ګناه رسۍ هغه کلک رانيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15552, 'Proverbs 5:23', 'Proverbs', 5, 23, '&nbsp;هغه به د خپل تربيت د کموالى په وجه مړ شى، او د خپل کم عقلتوب په سبب بې‌لارې شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15553, 'Proverbs 6:1', 'Proverbs', 6, 1, '&nbsp;زما زويه، کۀ چرې تا د خپل ګاونډى دپاره په ضمانت کښې څۀ اېښى وى، او يا تا د بل چا د قرض د ورکولو وعده کړې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15554, 'Proverbs 6:2', 'Proverbs', 6, 2, '&nbsp;کۀ تۀ چرې د خپلو خبرو په وجه په لټ کښې راګېر شوے يې، او په دام کښې د خپلې خولې د لاسه راګېر شوے يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15555, 'Proverbs 6:3', 'Proverbs', 6, 3, '&nbsp;نو بيا زما زويه، په دې کولو سره تۀ د خپل ګاونډى په لاسونو کښې پرېوتې، نو د هغۀ د دام نه د خلاصېدو دپاره، هغۀ له ورشه او خپل ځان کمزورے کړه او هغۀ ته مِنت زارى وکړه چې هغه تا د دې ذمه وارۍ نه آزاد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15556, 'Proverbs 6:4', 'Proverbs', 6, 4, '&nbsp;زر ورشه مۀ اودۀ کېږه او خپلې سترګې مرغۍ مرغۍ کېدو ته مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15557, 'Proverbs 6:5', 'Proverbs', 6, 5, '&nbsp;نو خپل ځان لکه د هوسۍ په شان د ښکارى نه او لکه د مارغۀ په شان خپل ځان د ښکارى د جال نه آزاد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15558, 'Proverbs 6:6', 'Proverbs', 6, 6, '&nbsp;ناراسته خلقو مېږو ته وګورئ، او د هغوئ په چال چلن باندې غور وکړئ او هوښيار شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15559, 'Proverbs 6:7', 'Proverbs', 6, 7, '&nbsp;دوئ نۀ مشر لرى، او نۀ څوک آفسر او نۀ حکمران لرى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15560, 'Proverbs 6:8', 'Proverbs', 6, 8, '&nbsp;خو دوئ په اوړى کښې خپل خوراک راټولوى، او خپل ځان دپاره خوراک په لو کښې راجمع کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15561, 'Proverbs 6:9', 'Proverbs', 6, 9, '&nbsp;خو تۀ ناراسته سړيه ترڅو پورې به پروت يې؟ او تۀ به کله د خوب نه راپاڅې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15562, 'Proverbs 6:10', 'Proverbs', 6, 10, '&nbsp;تۀ وائې، ”لږ وخت دپاره به اودۀ شم، او سترګې به پټې کړم، لږ به خپل لاسونه راغونډ کړم او آرام به وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15563, 'Proverbs 6:11', 'Proverbs', 6, 11, '&nbsp;نو بيا به غريبى او نيستى د وسله بند ډاکو په شان په تا باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15564, 'Proverbs 6:12', 'Proverbs', 6, 12, '&nbsp;بدمعاشان او کمينه خلق، ټوله ورځ تش دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15565, 'Proverbs 6:13', 'Proverbs', 6, 13, '&nbsp;هغوئ سترګې وهى او ستا د دوکه کولو دپاره په پښو او ګوتو اِشارې کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15566, 'Proverbs 6:14', 'Proverbs', 6, 14, '&nbsp;د هغوئ کاږۀ زړونه خرابې منصوبې جوړوى، نو دغه شان هغوئ تل په هر ځائ کښې سرخوږے پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15567, 'Proverbs 6:15', 'Proverbs', 6, 15, '&nbsp;نو په هم دې وجه په داسې کس باندې ناګهانى افت راځى، او ناګهانه به هغه ټوټې ټوټې شى او بيا به د جوړېدو نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15568, 'Proverbs 6:16', 'Proverbs', 6, 16, '&nbsp;شپږ څيزونه دى چې مالِک خُدائ ترې نه نفرت کوى بلکې اووۀ څيزونه دى چې مالِک خُدائ هغه نۀ شى برداشت کولے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15569, 'Proverbs 6:17', 'Proverbs', 6, 17, '&nbsp;مغروره سترګې، دروغژنه ژبه، هغه لاسونه چې بې‌ګناه وينه تويوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15570, 'Proverbs 6:18', 'Proverbs', 6, 18, '&nbsp;هغه زړۀ چې بدې منصوبې جوړوى، هغه پښې چې د شرارت طرف ته منډې وهى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15571, 'Proverbs 6:19', 'Proverbs', 6, 19, '&nbsp;دروغژن ګواه څوک چې دروغ وائى، او هغه کس چې د خاندان په مينځ کښې سرخوږے پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15572, 'Proverbs 6:20', 'Proverbs', 6, 20, '&nbsp;زما زويه، د پلار په حُکمونو عمل کوه، او د خپلې مور لارښودنه مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15573, 'Proverbs 6:21', 'Proverbs', 6, 21, '&nbsp;د هغوئ خبرې تل دپاره په خپل زړۀ کښې يادې ساته، او د هار په شان يې په خپله غاړه کښې ګرځوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15574, 'Proverbs 6:22', 'Proverbs', 6, 22, '&nbsp;هرکله چې تۀ روان يې نو هغه به ستا رهنمائى کوى، او کله چې اودۀ يې نو هغه به ستا حفاظت کوى، هرکله چې راويښ شې، نو هغه به درته مشوره درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15575, 'Proverbs 6:23', 'Proverbs', 6, 23, '&nbsp;نو د هغوئ حُکمونه ډيوه ده او د هغوئ هدايت رڼا ده، او د هغوئ اصلاح د ژوندون لار ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15576, 'Proverbs 6:24', 'Proverbs', 6, 24, '&nbsp;دا به تا د بدکاره ښځو نه ساتى، او د زناکارو ښځو د نرمو خبرو نه به دې ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15577, 'Proverbs 6:25', 'Proverbs', 6, 25, '&nbsp;د هغوئ په ښائست خپل زړۀ مۀ بائيله، او نۀ چې د هغې سترګې وهل تا راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15578, 'Proverbs 6:26', 'Proverbs', 6, 26, '&nbsp;يوه کنجره تۀ د يوې روټۍ په قيمت اخستے شى، خو د بل سړى د ښځې سره زنا به ستا د ژوند په قيمت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15579, 'Proverbs 6:27', 'Proverbs', 6, 27, '&nbsp;څوک په خپله جولۍ کښې بل شوے اور د کپړو سوزېدلو نه بغېر اوچتولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15580, 'Proverbs 6:28', 'Proverbs', 6, 28, '&nbsp;څوک په ګرمو سکروټو باندې بغېر د پښو پولۍ کېدو او سوزېدو نه ګرځېدلے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15581, 'Proverbs 6:29', 'Proverbs', 6, 29, '&nbsp;نو دا کس هم د هغه چا په شان دے څوک چې د بل چا د ښځې سره څملى، څوک هم چې د هغې سره زنا کوى نو د سزا نه به خلاص نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15582, 'Proverbs 6:30', 'Proverbs', 6, 30, '&nbsp;خلق هغه غل ته سپک نۀ ګورى څوک چې د خپلې لوږې د ختمېدو دپاره غلا کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15583, 'Proverbs 6:31', 'Proverbs', 6, 31, '&nbsp;خو کۀ هغه ګېر شى، نو هغه به اووۀ چنده ورکوى، کۀ څۀ هم د هغۀ د کور په ټول سامان يې قيمت پوره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15584, 'Proverbs 6:32', 'Proverbs', 6, 32, '&nbsp;خو کۀ يو سړے زنا کوى نو هغه بې‌حده کم عقل دے، ځکه چې هغه خپل ځان تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15585, 'Proverbs 6:33', 'Proverbs', 6, 33, '&nbsp;هغه به وهل وخورى او بې‌عزته به شى، او دا شرم به هيڅکله د هغۀ نه اخوا نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15586, 'Proverbs 6:34', 'Proverbs', 6, 34, '&nbsp;نو غېرت به يې د خاوند قهر راوپاروى او په بې‌رحمۍ سره به خپله بدله اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15587, 'Proverbs 6:35', 'Proverbs', 6, 35, '&nbsp;هغه به د دې په بدل کښې معاوضه نۀ قبلوى او هغه به رشوت هم رد کړى کۀ څومره ډېر هم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15588, 'Proverbs 7:1', 'Proverbs', 7, 1, '&nbsp;زما زويه، زما خبرې ځان سره وساته او زما احکام خپل ځان سره حفظ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15589, 'Proverbs 7:2', 'Proverbs', 7, 2, '&nbsp;زما په حُکمونو عمل کوه، نو تۀ به ژوندے پاتې شې. زما د تعليماتو داسې حفاظت وکړه لکه څنګه چې د سترګې د ګاټى کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15590, 'Proverbs 7:3', 'Proverbs', 7, 3, '&nbsp;هغه د خپلو ګوتو سره ونښلوه او د خپل زړۀ په تخته يې وليکه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15591, 'Proverbs 7:4', 'Proverbs', 7, 4, '&nbsp;حِکمت ته ووايه چې، ”تۀ زما خور يې،“ او پوهې ته خپل نزدې رشته‌دار ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15592, 'Proverbs 7:5', 'Proverbs', 7, 5, '&nbsp;دوئ به تا د زناکارې ښځې سره د تعلق نه وساتى، او هم به دې دوئ د زناکارې ښځې د دوکه کوونکو خبرو نه وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15593, 'Proverbs 7:6', 'Proverbs', 7, 6, '&nbsp;يو ځل ما د خپل کور د کړکۍ د جالۍ نه بهر وکتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15594, 'Proverbs 7:7', 'Proverbs', 7, 7, '&nbsp;نو ما څۀ ساده ځوانان وکتل، نو د دوئ په مينځ کښې مې يو کم عقل ځوان د نظر لاندې راغے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15595, 'Proverbs 7:8', 'Proverbs', 7, 8, '&nbsp;نو هغه د هغې د کور سره په نزدې کوڅه کښې روان وو، کومه لار چې د هغې کور ته تلې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15596, 'Proverbs 7:9', 'Proverbs', 7, 9, '&nbsp;د ماښام په وخت کښې، تيارۀ خوره شوه او شپه شروع شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15597, 'Proverbs 7:10', 'Proverbs', 7, 10, '&nbsp;نو بيا يوه ښځه بهر راغله چې د هغۀ سره مِلاو شى. هغې د کنجرتوب جامې اغوستې وې، او په غلط خيال سره چې هغه دوکه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15598, 'Proverbs 7:11', 'Proverbs', 7, 11, '&nbsp;هغه بې‌شرمه او بې‌حيا ښځه وه چې ټوله ورځ هواګيره ګرځېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15599, 'Proverbs 7:12', 'Proverbs', 7, 12, '&nbsp;هغه تل په کوڅو، او په چوکونو کښې ګرځى، او د ښار په هر ګوټ کښې ولاړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15600, 'Proverbs 7:13', 'Proverbs', 7, 13, '&nbsp;هغې هغۀ له غاړه ورکړه او ښُکل يې کړو، او په خپلو بې‌شرمو سترګو سره يې هغۀ ته ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');